222	    /// Writes `document` and WAITS for NSDocument's asynchronous save to
223	    /// finish, so the tool's answer is only sent once the package is really on
224	    /// disk and the agent can read it back.
225	    ///
226	    /// The wait is why `save_project` and `new_project` run on the server
227	    /// thread: `save(to:ofType:for:completionHandler:)` delivers its
228	    /// completion on the MAIN thread, which a main-thread wait would be
229	    /// occupying.
230	    func save(
231	        _ document: ProjectDocument, to url: URL, operation: NSDocument.SaveOperationType
232	    ) throws {
233	        guard !Thread.isMainThread else {
234	            throw ToolError(message: "Saving cannot run on the main thread.")
235	        }
236	        let semaphore = DispatchSemaphore(value: 0)
237	        let box = AgentBox<(any Error)?>()
238	        onMain {
239	            document.save(
240	                to: url, ofType: ProjectDocument.projectTypeIdentifier, for: operation
241	            ) { error in
242	                box.value = error
243	                semaphore.signal()
244	            }
245	        }
246	        guard semaphore.wait(timeout: .now() + 120) == .success else {
247	            throw ToolError(message: "Timed out saving \(url.lastPathComponent).")
248	        }
249	        if let error = box.value ?? nil {
250	            throw ToolError(message: error.localizedDescription)
251	        }
252	    }
