    /// Each kind's kernel.
    static let functions: [ScopeKind: String] = [
        .waveform: "framejob_waveform_bin", .parade: "framejob_parade_bin",
        .vectorscope: "framejob_vectorscope_bin", .histogram: "framejob_histogram_bin",
    ]

